local function getQuestObjectiveText(questID, objectiveIndex)
    local questIDNum = tonumber(questID)
    local objectiveIndexNum = tonumber(objectiveIndex)
    if not questIDNum or not objectiveIndexNum then
        return nil
    end

    if APR.GetQuestTextForProgressBar then
        local progressText = APR:GetQuestTextForProgressBar(questIDNum, objectiveIndexNum)
        if progressText then
            return progressText
        end
    end

    local questData = APR.ActiveQuests and APR.ActiveQuests[questIDNum]
    local activeObjective = questData and questData.objectives and questData.objectives[objectiveIndexNum] or nil
    if activeObjective and activeObjective.text then
        return activeObjective.text
    end

    local questObjectives = C_QuestLog.GetQuestObjectives and C_QuestLog.GetQuestObjectives(questIDNum) or nil
    local objective = questObjectives and questObjectives[objectiveIndexNum] or nil
    return objective and objective.text or nil
end--[[APR_DIAG]]; getQuestObjectiveText = APRTrace("APR-Core/utils/UIUtils.lua:150:getQuestObjectiveText#12", getQuestObjectiveText)--[[/APR_DIAG]]

--- Add quest/scenario tooltip details.
--- @param tooltip table GameTooltip-like object
--- @param questID string|number
--- @param options table|nil
function APR:AddQuestTooltipDetails(tooltip, questID, options)
    if not tooltip then
        return
    end

    options = options or {}

    if options.addHeader ~= false then
        APR:AddTooltipLine(tooltip, L["QUEST_INFO"], "general", "base")
    end

    local questIDText = (questID ~= nil) and tostring(questID) or "?"
    local questIDNum = tonumber(questIDText)
    local objectiveIndex = options.objectiveIndex
    local objectiveText = options.objectiveText

    if options.isScenario then
        addScenarioDetails(tooltip, questIDText, objectiveIndex, objectiveText)
        return
    end

    -- Order requested: ID, Name, StorylineName, Campaign, Objectives
    addKeyValueLine(tooltip, ID, questIDText)

    if questIDNum then
        local questTitle = APR:GetQuestTitle(questIDNum)
        if questTitle then
            addKeyValueLine(tooltip, NAME, questTitle)
        end
    end

    if options.includeStoryline ~= false then
        addStorylineLine(tooltip, questIDNum)
    end

    if options.includeCampaign ~= false then
        local isCampaign = questIDNum and APR:IsCampaignQuest(questIDNum)
        addKeyValueLine(tooltip, L["Campaign"], tooltipBoolean(isCampaign and true or false))
    end

    if objectiveIndex ~= nil and objectiveText ~= nil then
        addKeyValueLine(tooltip, OBJECTIVES_LABEL, tostring(objectiveIndex) .. " - " .. tostring(objectiveText))
    end
end--[[APR_DIAG]]; APR.AddQuestTooltipDetails = APRTrace("APR-Core/utils/UIUtils.lua:179:APR:AddQuestTooltipDetails#13", APR.AddQuestTooltipDetails)--[[/APR_DIAG]]

--- Add the aggregated tooltip details for a route step.
--- Mirrors the quest-detail blocks shown on CurrentStep containers, but merges
--- every relevant quest/scenario entry into a single tooltip.
--- @param tooltip table GameTooltip-like object
--- @param step table|nil
--- @return boolean addedDetails true when at least one detail block was added
function APR:AddStepTooltipDetails(tooltip, step)
    if not tooltip or type(step) ~= "table" then
        return false
    end

    local addedDetails = 0
    local seenTokens = {}
    local handledQuestIDs = {}

    local function addDetails(questID, options)
        if questID == nil then
            return
        end

        options = options or {}

        local token = table.concat({
            options.isScenario and "scenario" or "quest",
            tostring(questID),
            tostring(options.objectiveIndex or ""),
        }, ":")

        if seenTokens[token] then
            return
        end

        seenTokens[token] = true
        handledQuestIDs[tostring(questID)] = true

        if addedDetails > 0 then
            tooltip:AddLine(" ")
        end

        APR:AddQuestTooltipDetails(tooltip, questID, options)
        addedDetails = addedDetails + 1
    end--[[APR_DIAG]]; addDetails = APRTrace("APR-Core/utils/UIUtils.lua:239:addDetails#15", addDetails)--[[/APR_DIAG]]

    local objectiveStep = step.Qpart or step.QpartPart
    if type(objectiveStep) == "table" then
        local sortedQuestIDs = {}
        for questID in pairs(objectiveStep) do
            table.insert(sortedQuestIDs, questID)
        end
        table.sort(
            sortedQuestIDs,

                --[[APR_DIAG]]APRTrace("APR-Core/utils/UIUtils.lua:276:callback#16", --[[/APR_DIAG]]function(a, b)
                    return tostring(a) < tostring(b)
                end--[[APR_DIAG]])--[[/APR_DIAG]]
        )

        for _, questID in ipairs(sortedQuestIDs) do
            local objectiveIndexes = objectiveStep[questID]
            if type(objectiveIndexes) == "table" then
                local sortedObjectiveIndexes = {}
                for _, objectiveIndex in ipairs(objectiveIndexes) do
                    table.insert(sortedObjectiveIndexes, objectiveIndex)
                end
                table.sort(
                    sortedObjectiveIndexes,

                        --[[APR_DIAG]]APRTrace("APR-Core/utils/UIUtils.lua:291:callback#17", --[[/APR_DIAG]]function(a, b)
                            return tonumber(a) < tonumber(b)
                        end--[[APR_DIAG]])--[[/APR_DIAG]]
                )
                for _, objectiveIndex in ipairs(sortedObjectiveIndexes) do
                    addDetails(questID, {
                        objectiveIndex = objectiveIndex,
                        objectiveText = getQuestObjectiveText(questID, objectiveIndex),
                        includeCampaign = true,
                        includeStoryline = true,
                    })
                end
            end
        end
    end

    local scenarioData = step.Scenario
    if type(scenarioData) == "table" and scenarioData.scenarioID then
        local criteriaInfo = nil
        if
            C_ScenarioInfo
            and C_ScenarioInfo.GetCriteriaInfoByStep
            and scenarioData.stepID
            and scenarioData.criteriaIndex
        then
            criteriaInfo = C_ScenarioInfo.GetCriteriaInfoByStep(scenarioData.stepID, scenarioData.criteriaIndex)
        end

        addDetails(scenarioData.scenarioID, {
            isScenario = true,
            objectiveIndex = scenarioData.criteriaID or scenarioData.criteriaIndex,
            objectiveText = criteriaInfo and criteriaInfo.description or nil,
        })

        if scenarioData.questID then
            handledQuestIDs[tostring(scenarioData.questID)] = true
        end
    end

    local stepQuestIDs = APR.GetStepQuestIDs and APR:GetStepQuestIDs(step) or {}
    for _, questID in ipairs(stepQuestIDs) do
        if not handledQuestIDs[tostring(questID)] then
            addDetails(questID, {
                includeCampaign = true,
                includeStoryline = true,
            })
        end
    end

    return addedDetails > 0
end--[[APR_DIAG]]; APR.AddStepTooltipDetails = APRTrace("APR-Core/utils/UIUtils.lua:230:APR:AddStepTooltipDetails#14", APR.AddStepTooltipDetails)--[[/APR_DIAG]]

--- Performs the "Love" action for the APR module.
-- Updates APR color scheme for Saint Valentin (Feb 14th).
function APR:Love()
    local currentDate = C_DateAndTime.GetCurrentCalendarTime()
    if currentDate.month == 2 and currentDate.monthDay == 14 then
        APR.Color.blue = APR.Color.pink
        APR.Color.yellow = APR.Color.pink
        self.loveColorsPending = true
        self:ApplyLoveColors()
    end
end--[[APR_DIAG]]; APR.Love = APRTrace("APR-Core/utils/UIUtils.lua:345:APR:Love#18", APR.Love)--[[/APR_DIAG]]

-- Apply Love day color overrides to live widgets
function APR:ApplyLoveColors()
    if not self.loveColorsPending then
        return
    end

    local profile = APR.settings and APR.settings.profile
    if not profile then
        return
    end

    local pink = APR.Color.pink or { 1, 0, 1, 1 }
    local function copyWithAlpha(existing)
        local alpha = (existing and existing[4]) or 1
        return { pink[1], pink[2], pink[3], alpha }
    end--[[APR_DIAG]]; copyWithAlpha = APRTrace("APR-Core/utils/UIUtils.lua:367:copyWithAlpha#20", copyWithAlpha)--[[/APR_DIAG]]

    for colorKey in pairs(self.STATUS_BAR_COLOR_DEFAULTS) do
        profile[colorKey] = copyWithAlpha(profile[colorKey])
    end
    self:RefreshStatusBarColors()

    self.loveColorsPending = false
end--[[APR_DIAG]]; APR.ApplyLoveColors = APRTrace("APR-Core/utils/UIUtils.lua:356:APR:ApplyLoveColors#19", APR.ApplyLoveColors)--[[/APR_DIAG]]

