--- Check if frames should be hidden based on various conditions
--- Centralizes frame hiding logic to avoid duplication across multiple frame modules
---@return boolean true if frames should be hidden
function APR:ShouldHideFrames()
    return not self.settings.profile.currentStepShow
        or not self.settings.profile.enableAddon
        or APR:IsPetBattleActive()
        or not self:IsInstanceWithUI()
end--[[APR_DIAG]]; APR.ShouldHideFrames = APRTrace("APR-Core/utils/UIUtils.lua:453:APR:ShouldHideFrames#25", APR.ShouldHideFrames)--[[/APR_DIAG]]

--- Check if AFK frame is visible, active (timer running), and should snap
--- Implements proper state verification for safe anchor frame selection
---@return boolean true if AFK frame should be used as anchor
function APR:IsAFKFrameActiveShouldSnap()
    -- Quick exit if AFK module or settings not loaded
    if not self.AFK or not self.settings or not self.settings.profile then
        return false
    end

    -- Check if snapping is enabled in settings
    if not self.settings.profile.afkSnapToCurrentStep then
        return false
    end

    -- Check if AFK frame exists and is shown
    local afkFrame = _G.AfkFrameScreen
    if not afkFrame or not afkFrame:IsShown() then
        return false
    end

    -- Real and test timers both reserve space while their countdown is active.
    if not self.AFK.timerEnd or self.AFK.timerEnd <= GetTime() then
        return false
    end

    return true
end--[[APR_DIAG]]; APR.IsAFKFrameActiveShouldSnap = APRTrace("APR-Core/utils/UIUtils.lua:463:APR:IsAFKFrameActiveShouldSnap#26", APR.IsAFKFrameActiveShouldSnap)--[[/APR_DIAG]]

--- Return true when the quest-step UI key belongs to transient navigation guidance.
---@param key string|number|nil
---@return boolean
function APR:IsNavigationQuestUiKey(key)
    if type(key) ~= "string" then
        return false
    end

    if
        self.navigation
        and (
            key == self.navigation.NavigationDividerStepKey
            or key == self.navigation.NavigationStepKey
            or key == self.navigation.ErrorStepKey
        )
    then
        return true
    end

    for _, pattern in ipairs(NAVIGATION_QUEST_UI_KEY_PATTERNS) do
        if key:match(pattern) then
            return true
        end
    end

    return false
end--[[APR_DIAG]]; APR.IsNavigationQuestUiKey = APRTrace("APR-Core/utils/UIUtils.lua:491:APR:IsNavigationQuestUiKey#27", APR.IsNavigationQuestUiKey)--[[/APR_DIAG]]

--- Return true when the extra-line UI key belongs to transient navigation guidance.
---@param key string|number|nil
---@return boolean
function APR:IsNavigationExtraTextUiKey(key)
    if not self.navigation then
        return false
    end

    return key == self.navigation.ErrorDestinationLineKey or key == "DESTINATION"
end--[[APR_DIAG]]; APR.IsNavigationExtraTextUiKey = APRTrace("APR-Core/utils/UIUtils.lua:519:APR:IsNavigationExtraTextUiKey#28", APR.IsNavigationExtraTextUiKey)--[[/APR_DIAG]]

--- Get the proper snap anchor frame implementing the snap hierarchy
--- Other frames can anchor to this in order: Fillers > AFK > CurrentStep
--- FillersFrame calls with excludeFillers=true to avoid anchoring to itself
---@param excludeFillers boolean|nil If true, skip Fillers in the hierarchy (used by FillersFrame)
---@return table|nil anchorFrame The frame to anchor to, or nil if unavailable
---@return number|nil anchorHeight Height of the anchor frame, or nil if unavailable
function APR:GetSnapAnchorFrame(excludeFillers)
    -- Default to CurrentStep panel
    local currentStepPanel = _G.CurrentStepScreenPanel
    if not currentStepPanel or not currentStepPanel:IsShown() then
        return nil, nil
    end

    -- Hierarchy: Fillers (highest, optional) -> AFK (medium) -> CurrentStep (fallback)

    -- 1. Check Fillers frame (highest priority, unless explicitly excluded)
    if not excludeFillers and self.fillersFrame and self.settings and self.settings.profile then
        local fillersFrame = self.fillersFrame.Frame
        if fillersFrame and fillersFrame:IsShown() and self.settings.profile.fillersFrameSnapToCurrentStep then
            return fillersFrame, fillersFrame:GetHeight()
        end
    end

    -- 2. Check AFK frame (medium priority)
    if self:IsAFKFrameActiveShouldSnap() then
        local afkFrame = _G.AfkFrameScreen
        return afkFrame, afkFrame:GetHeight()
    end

    -- 3. Default to CurrentStep frame (always available as fallback)
    local contentHeight = (self.currentStep and self.currentStep.GetContentHeight)
            and self.currentStep:GetContentHeight(false)
        or 0

    if not contentHeight or contentHeight <= 0 then
        contentHeight = currentStepPanel:GetHeight() or 300
    end

    return currentStepPanel, contentHeight
end--[[APR_DIAG]]; APR.GetSnapAnchorFrame = APRTrace("APR-Core/utils/UIUtils.lua:533:APR:GetSnapAnchorFrame#29", APR.GetSnapAnchorFrame)--[[/APR_DIAG]]

--- Create a standard APR UI frame with default backdrop styling.
---@param name string
---@param parent table
---@param width number
---@param height number
---@param template string|nil
---@param skinOptions table|nil
---@return table
function APR:CreateStandardFrame(name, parent, width, height, template, skinOptions)
    local frame = CreateFrame("Frame", name, parent or UIParent, template or "BackdropTemplate")
    frame:SetSize(width, height)
    frame:SetFrameStrata("MEDIUM")
    frame:SetClampedToScreen(true)
    frame:SetBackdrop({
        bgFile = "Interface\\BUTTONS\\WHITE8X8",
        tile = true,
        tileSize = 16,
    })
    APR:SetPanelColor(frame, APR.Color.defaultBackdrop)
    if self.RegisterSkinTarget then
        self:RegisterSkinTarget(frame, "panel", skinOptions or { preserveBackground = true })
    end
    return frame
end--[[APR_DIAG]]; APR.CreateStandardFrame = APRTrace("APR-Core/utils/UIUtils.lua:576:APR:CreateStandardFrame#30", APR.CreateStandardFrame)--[[/APR_DIAG]]

